private fun menuActions(name: String): List<PanelCommand> = when(name) {
    "File"->(listOf<Pair<String,()->Unit>>(
        ui(R.string.ui_new) to {confirmReplacement {dimensionsDialog(false,true)}},
        ui(R.string.ui_load_image) to {confirmReplacement {launchOpen(false)}},
        ui(R.string.ui_save) to {requestSave(false)},
        ui(R.string.save20_title) to {showSaveOptions(savedTarget?.options?.format ?: ImageFormat.PNG)},
        ui(R.string.ui_export_as23) to {showSaveOptions(exportOptions.format,export=true)},
        ui(R.string.ui_save_and_share) to {showSaveOptions(exportOptions.format,true,export=true)},
        ui(R.string.ui_image_assembly) to {openAssembly()},
        ui(R.string.ui_how_to_use) to {showHelp()},
        ui(R.string.ui_about_credits23) to {showAboutOptions()}
    ) + if(autosaveBlocked || autosave.recoveryCopies().isNotEmpty()) listOf(ui(R.string.ui_export_recovery_copy) to {requestRecoveryExport()}) else emptyList()).map {PanelCommand(it.first,it.second)}

private fun confirmReplacement(action: () -> Unit) {
    paintCanvas.applyPending()
    if (!document.dirty) { action(); return }
    EditorDialogBuilder(this).setTitle(ui(R.string.ui_save_your_changes)).setMessage(ui(R.string.ui_your_current_image_has_unsaved_changes))
        .setPositiveButton(ui(R.string.ui_save_a5d0d9)) { _, _ -> afterSave = action; requestSave(false) }
        .setNeutralButton(ui(R.string.ui_discard_changes23)) { _, _ -> action() }.setNegativeButton(ui(R.string.ui_keep_editing23), null).show()

private fun requestSave(jpeg: Boolean) {
    if(jpeg) {showSaveOptions(ImageFormat.JPEG);return}
    val target=savedTarget
    if(target==null) showSaveOptions(ImageFormat.PNG)
    else {exportOptions=target.options;isExporting=false;shareAfterSave=false;writeImage(target.uri)}
}
private fun showSaveOptions(format: ImageFormat,share: Boolean=false,export: Boolean=false) {
    val prefs=getSharedPreferences("export",MODE_PRIVATE)
    val remembered=savedTarget?.options?.takeIf {!export && it.format==format}
    SaveOptionsDialog(this,remembered ?: ExportOptions(format,prefs.getInt("quality",95),prefs.getBoolean("lossless",true),prefs.getBoolean("dither",true),prefs.getBoolean("tiff_compressed",true),prefs.getInt("ico_size",256),prefs.getInt("ascii_columns",100),prefs.getBoolean("ascii_invert",false)),share,
        confirm={request ->
            exportOptions=request.options;shareAfterSave=share;isExporting=export
            val savedPrefs=prefs.edit().putInt("quality",exportOptions.quality).putBoolean("dither",exportOptions.dither).putBoolean("tiff_compressed",exportOptions.tiffCompressed).putInt("ico_size",exportOptions.icoSize).putInt("ascii_columns",exportOptions.asciiColumns).putBoolean("ascii_invert",exportOptions.asciiInvert)
            if(exportOptions.format.supportsLossless) savedPrefs.putBoolean("lossless",exportOptions.lossless)
            savedPrefs.apply()
            chooseSaveLocation(request.fileName)
        },cancel={afterSave=null;shareAfterSave=false},initialFilename=filename,export=export,imageCredits=ImageCredit.text(document.imageCredits),
        legacyCredits=if(ImageCreditArchive.hasRecords(this)) ::showLegacyImageCredits else null).show()
}
private fun chooseSaveLocation(proposedName: String=filename) {
    launchPicker(Intent(Intent.ACTION_CREATE_DOCUMENT).apply {
        addCategory(Intent.CATEGORY_OPENABLE);type=exportOptions.format.mime
        addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION or Intent.FLAG_GRANT_WRITE_URI_PERMISSION or Intent.FLAG_GRANT_PERSISTABLE_URI_PERMISSION)
        putExtra(Intent.EXTRA_TITLE,ExportNames.withExtension(proposedName.ifBlank {ui(R.string.ui_untitled)},exportOptions.format))
    },SAVE_IMAGE)

private fun writeImage(uri: Uri) {
    paintCanvas.applyPending()
    beginIo()
    val snapshot=document.bitmap
    val options=exportOptions;val exporting=isExporting;val sharing=shareAfterSave;shareAfterSave=false
    worker.execute {
        var encoded: File?=null
        try {
            val directory=File(cacheDir,"images").apply {mkdirs()}
            val file=File.createTempFile("AN-Paint-",options.format.extension,directory);encoded=file
            ImageExporter.encode(snapshot,file,options,ImageMemoryPolicy.forDevice(this).workingBytes)
            contentResolver.openOutputStream(uri,"wt")?.use {output -> file.inputStream().use {it.copyTo(output)}}
                ?: throw IOException(ui(R.string.ui_the_selected_location_is_not_writable))
            val name=displayName(uri)
            if(sharing) encoded=null
            runOnUiThread {if(!isDestroyed) {
                if(!exporting) {filename=name;savedTarget=SavedTarget(uri,name,options);document.markSaved();scheduleAutosave()};endIo();LocaleTypography.showMessage(this,ui(R.string.ui_saved, name),Toast.LENGTH_SHORT)
                if(sharing) shareSavedImage(file,options.format)
                val action=afterSave;afterSave=null
                if(exporting && action!=null) message(ui(R.string.ui_export_did_not_save23)) else action?.invoke()
            }}
        } catch(error: Exception) {ioFailed(ui(R.string.ui_could_not_save_image),error)}
          catch(error: OutOfMemoryError) {ioFailed(ui(R.string.ui_not_enough_memory_to_save_in_this_format),error)}
        finally {encoded?.delete()}
    }
}

private fun shareSavedImage(file: File,format: ImageFormat) {
    try {
        val uri=androidx.core.content.FileProvider.getUriForFile(this,"$packageName.fileprovider",file)
        val send=Intent(Intent.ACTION_SEND).apply {
            type=format.mime;putExtra(Intent.EXTRA_STREAM,uri)
            clipData=android.content.ClipData.newRawUri(ui(R.string.ui_an_paint_image),uri)
            addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION)
        }
        startActivity(Intent.createChooser(send,ui(R.string.ui_share_saved_image)))
    } catch(error: Exception) {message(ui(R.string.ui_the_image_was_saved_but_android_could_not, error.message))}

private fun beginIo() { operationsInFlight++; busy = true; lastIoError = null; paintCanvas.isEnabled = false; updateStatus() }
private fun endIo() { operationsInFlight = (operationsInFlight - 1).coerceAtLeast(0); busy = operationsInFlight > 0; paintCanvas.isEnabled = !busy; updateStatus(); if (!busy && autosaveReady && draftGeneration != savedDraftGeneration && draftGeneration != failedDraftGeneration) { autosaveHandler.removeCallbacks(saveDraft); autosaveHandler.postDelayed(saveDraft,if (stopped) 0 else 1500) }; if(!busy) deliverPendingInputs() }
private fun ioFailed(prefix: String, e: Throwable) {
    runOnUiThread { if (!isDestroyed) { afterSave = null; endIo(); lastIoError = "$prefix. ${e.message ?: ui(R.string.ui_try_a_different_file_or_location)}"; message(lastIoError!!) } }
}

enum class ImageFormat(private val displayLabel: String,val mime: String,val extension: String,val supportsLossless: Boolean=false) {
    // Append values to retain the saved-state ordinals used by earlier builds.
    PNG("PNG", "image/png", ".png"), JPEG("JPEG", "image/jpeg", ".jpg"),
    JPEG_XL("JPEG XL", "image/jxl", ".jxl",true), WEBP("WebP","image/webp",".webp",true),
    HEIC("HEIC","image/heic",".heic"), AVIF("AVIF","image/avif",".avif",true),
    BMP("BMP","image/bmp",".bmp"), GIF("GIF","image/gif",".gif"),
    DIB("DIB","image/x-dib",".dib"), TIFF("TIFF","image/tiff",".tif"),
    ICO("ICO","image/vnd.microsoft.icon",".ico"), BASE64("Base64 text","text/plain",".txt"),
    ASCII_ART("ASCII art","text/plain",".txt");
    val label: String get()=when(this) {BASE64->ui(R.string.formats22_base64_label);ASCII_ART->ui(R.string.formats22_ascii_label);else->displayLabel}
    val supportsQuality: Boolean get() = this in listOf(JPEG,JPEG_XL,WEBP,HEIC,AVIF)
    val canSaveLosslessly: Boolean get() = this in listOf(PNG,JPEG_XL,WEBP,AVIF,BMP,DIB,TIFF,BASE64)
    val isDerivedExport: Boolean get() = this in listOf(ICO,BASE64,ASCII_ART)
}

/** One options panel precedes Android's destination picker for every Save as format. */
class SaveOptionsDialog(private val activity: Activity,private val initial: ExportOptions,
    private val share: Boolean=false,private val confirm: (SaveRequest)->Unit,private val cancel: ()->Unit,
    private val initialFilename: String="", private val export: Boolean=false, private val imageCredits: String="",
    private val legacyCredits: (()->Unit)?=null) {
    fun show(): AlertDialog {
        lateinit var dialog: AlertDialog
        val formats=ImageFormat.values().filter {share || it.isDerivedExport==export}
        var format=initial.format.takeIf {it in formats} ?: formats.first();var quality=initial.quality.coerceIn(1,100);var lossless=initial.lossless
        val body=LinearLayout(activity).apply {orientation=LinearLayout.VERTICAL;setPadding(24,12,24,12)}
        body.addView(TextView(activity).apply {text=ui(when {share->R.string.ui_share_explanation34;export->R.string.ui_export_explanation23;else->R.string.ui_save_explanation23})})
        body.addView(TextView(activity).apply {text=ui(R.string.save20_file_name)})
        val filename=EditText(activity).apply {
            tag="export_filename";setSingleLine(true)
            inputType=InputType.TYPE_CLASS_TEXT or InputType.TYPE_TEXT_FLAG_CAP_SENTENCES
            setText(ExportNames.withExtension(initialFilename.ifBlank {ui(R.string.ui_untitled)},format))
            contentDescription=ui(R.string.save20_file_name)
            selectAll()
        }
        body.addView(filename,LinearLayout.LayoutParams(-1,-2))
        body.addView(TextView(activity).apply {text=ui(R.string.save20_file_format)})
        val losslessBox=CheckBox(activity).apply {tag="export_lossless";isChecked=lossless}

    // Credits contain original names and URLs. Keep selectable native text in a bounded
    // scrolling column even when the surrounding interface uses vertical text.
    creditsPanel?.let {form.addView(ScrollView(activity).apply {addView(VerticalUi.detach(it))},LinearLayout.LayoutParams((264*d).toInt(),(tall*d).toInt()))}
    legacyButton?.let {VerticalUi.caption(it,tall);form.addView(VerticalUi.detach(it))}
    form.addView(prose(ui(when {share->R.string.ui_share_explanation34;export->R.string.ui_export_explanation23;else->R.string.ui_save_explanation23})))
    form.layoutDirection=if(VerticalText.uiDirection(activity)==TextDirection.VERTICAL_RL) View.LAYOUT_DIRECTION_RTL else View.LAYOUT_DIRECTION_LTR
    form
} else ScrollView(activity).apply {addView(body)}
dialog=EditorDialogBuilder(activity).setTitle(if(share) ui(R.string.ui_save_and_share_41edb4) else ui(if(export) R.string.ui_export_as23 else R.string.save20_title))
    .setView(content)
    .setPositiveButton(ui(R.string.ui_choose_location),null)
    .setNegativeButton(ui(R.string.ui_cancel)) {_,_ -> cancel()}.setOnCancelListener {cancel()}.create()
dialog.setOnShowListener {
    dialog.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener {
        val name=filename.text.toString()
        if(!ExportNames.valid(name,format)) filename.error=ui(R.string.save20_invalid_name)
        else {
            confirm(SaveRequest(ExportOptions(format,quality,format.supportsLossless && lossless,ditherBox.isChecked,tiffCompressionBox.isChecked,icoSize,asciiColumns,asciiInvert.isChecked),ExportNames.withExtension(name,format)))
            dialog.dismiss()
        }
    }
}
